CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE argus_role AS ENUM ('owner','admin','analyst','approver');
CREATE TYPE model_status AS ENUM ('candidate','shadow','approved','champion','retired');
CREATE TABLE businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clerk_org_id text UNIQUE NOT NULL, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Kolkata', currency char(3) NOT NULL DEFAULT 'INR', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clerk_user_id text UNIQUE NOT NULL, email_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (business_id uuid REFERENCES businesses ON DELETE CASCADE, user_id uuid REFERENCES users ON DELETE CASCADE, role argus_role NOT NULL, permission_snapshot jsonb NOT NULL, PRIMARY KEY (business_id,user_id));
CREATE TABLE import_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, idempotency_key text NOT NULL, checksum text NOT NULL, schema_version text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (business_id,idempotency_key));
CREATE TABLE canonical_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, import_id uuid NOT NULL REFERENCES import_batches, checksum text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, snapshot_id uuid NOT NULL REFERENCES canonical_snapshots, source_record_id text NOT NULL, purchase_id text NOT NULL, supplier_id text NOT NULL, sku text NOT NULL, order_date date NOT NULL, receipt_date date, quantity numeric NOT NULL CHECK (quantity > 0), base_cost numeric NOT NULL CHECK (base_cost >= 0), freight numeric NOT NULL DEFAULT 0, tax numeric NOT NULL DEFAULT 0, landed_unit_cost numeric NOT NULL CHECK (landed_unit_cost >= 0), payment_term_days integer, UNIQUE (business_id,snapshot_id,source_record_id));
CREATE TABLE model_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, model_kind text NOT NULL, version text NOT NULL, status model_status NOT NULL, code_commit text NOT NULL, dependency_hash text NOT NULL, feature_schema_version text NOT NULL, training_snapshot_id uuid REFERENCES canonical_snapshots, metrics jsonb NOT NULL, artifact_uri text NOT NULL, artifact_checksum text NOT NULL, rollback_target_id uuid REFERENCES model_versions, promoted_by uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (business_id,model_kind,version));
CREATE TABLE analysis_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, snapshot_id uuid NOT NULL REFERENCES canonical_snapshots, model_manifest jsonb NOT NULL, status text NOT NULL, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (business_id,idempotency_key));
CREATE TABLE decision_packages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, analysis_run_id uuid NOT NULL UNIQUE REFERENCES analysis_runs, package jsonb NOT NULL, checksum text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, actor_user_id uuid REFERENCES users, event_type text NOT NULL, request_id text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY; ALTER TABLE import_batches ENABLE ROW LEVEL SECURITY; ALTER TABLE canonical_snapshots ENABLE ROW LEVEL SECURITY; ALTER TABLE purchase_lines ENABLE ROW LEVEL SECURITY; ALTER TABLE model_versions ENABLE ROW LEVEL SECURITY; ALTER TABLE analysis_runs ENABLE ROW LEVEL SECURITY; ALTER TABLE decision_packages ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['memberships','import_batches','canonical_snapshots','purchase_lines','model_versions','analysis_runs','decision_packages','audit_events'] LOOP EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (business_id = nullif(current_setting(''argus.tenant_id'', true), '''')::uuid) WITH CHECK (business_id = nullif(current_setting(''argus.tenant_id'', true), '''')::uuid)', t); END LOOP; END $$;
